isolation-forest.pseudocode:
def c(n):  # 크기 n의 평균 경로 길이 (정규화 상수)
    if n <= 1:
        return 0.0
    return 2 * (log(n - 1) + 0.5772) - 2 * (n - 1) / n

def build_itree(X, d, max_d):  # d: 현재 깊이
    if d >= max_d or len(X) <= 1:
        return Leaf(size=len(X))
    q = random_feature(X)  # 무작위 속성
    p = random_uniform(min_of(X, q), max_of(X, q))
    L = [x for x in X if x[q] < p]  # 무작위 분할값 p
    R = [x for x in X if x[q] >= p]
    return Node(q, p, build_itree(L, d + 1, max_d),
                build_itree(R, d + 1, max_d))

def path_length(x, node, d=0):
    if node.is_leaf:
        return d + c(node.size)  # 미분할 잔여 점 보정
    nxt = node.left if x[node.q] < node.p else node.right
    return path_length(x, nxt, d + 1)

def score(x, trees, psi):  # 1에 가까울수록 이상치
    E = mean(path_length(x, t) for t in trees)
    return 2 ** (-E / c(psi))
